use PortLibs\Pandoc\EpubContainerException;
use PortLibs\Pandoc\PandocConverter;
use PortLibs\Pandoc\WordPressBlockWriter;

function pandoc_epub_test_zip(string $path): ZipArchive
{
    $zip = new ZipArchive();
    if ($zip->open($path, ZipArchive::OVERWRITE) !== true) {
        throw new RuntimeException('Unable to create temporary EPUB package');
    }

    $zip->addFromString('mimetype', 'application/epub+zip');
    if (!$zip->setCompressionName('mimetype', ZipArchive::CM_STORE)) {
        throw new RuntimeException('Unable to store EPUB mimetype uncompressed');
    }

    return $zip;
}

function pandoc_epub_test_u16(string $bytes, int $offset): int
{
    $value = unpack('v', substr($bytes, $offset, 2));
    if (!is_array($value)) {
        throw new RuntimeException('Unable to read ZIP uint16 field');
    }

    return (int) $value[1];
}

function pandoc_epub_test_u32(string $bytes, int $offset): int
{
    $value = unpack('V', substr($bytes, $offset, 4));
    if (!is_array($value)) {
        throw new RuntimeException('Unable to read ZIP uint32 field');
    }

    return (int) $value[1];
}

function pandoc_epub_test_put_u16(string &$bytes, int $offset, int $value): void
{
    $bytes = substr_replace($bytes, pack('v', $value), $offset, 2);
}

function pandoc_epub_test_put_u32(string &$bytes, int $offset, int $value): void
{
    $bytes = substr_replace($bytes, pack('V', $value), $offset, 4);
}

function pandoc_epub_test_add_first_local_extra_field(string $path, string $extra): void
{
    $bytes = file_get_contents($path);
    if (!is_string($bytes) || substr($bytes, 0, 4) !== "PK\x03\x04") {
        throw new RuntimeException('Unable to patch EPUB ZIP local header');
    }

    $nameLength = pandoc_epub_test_u16($bytes, 26);
    $extraLength = pandoc_epub_test_u16($bytes, 28);
    $insertOffset = 30 + $nameLength + $extraLength;
    $extraBytes = strlen($extra);
    pandoc_epub_test_put_u16($bytes, 28, $extraLength + $extraBytes);

    $eocdOffset = strrpos($bytes, "PK\x05\x06");
    if (!is_int($eocdOffset)) {
        throw new RuntimeException('Unable to locate ZIP EOCD while patching EPUB fixture');
    }

    $centralDirectorySize = pandoc_epub_test_u32($bytes, $eocdOffset + 12);
    $centralDirectoryOffset = pandoc_epub_test_u32($bytes, $eocdOffset + 16);
    $centralDirectory = substr($bytes, $centralDirectoryOffset, $centralDirectorySize);
    $offset = 0;
    $centralLength = strlen($centralDirectory);
    while ($offset + 46 <= $centralLength && substr($centralDirectory, $offset, 4) === "PK\x01\x02") {
        $localOffset = pandoc_epub_test_u32($centralDirectory, $offset + 42);
        if ($localOffset >= $insertOffset) {
            pandoc_epub_test_put_u32($centralDirectory, $offset + 42, $localOffset + $extraBytes);
        }

        $fileNameLength = pandoc_epub_test_u16($centralDirectory, $offset + 28);
        $centralExtraLength = pandoc_epub_test_u16($centralDirectory, $offset + 30);
        $commentLength = pandoc_epub_test_u16($centralDirectory, $offset + 32);
        $offset += 46 + $fileNameLength + $centralExtraLength + $commentLength;
    }

    $tail = substr($bytes, $eocdOffset);
    pandoc_epub_test_put_u32($tail, 16, $centralDirectoryOffset + $extraBytes);
    $patched = substr($bytes, 0, $insertOffset)
        . $extra
        . substr($bytes, $insertOffset, $centralDirectoryOffset - $insertOffset)
        . $centralDirectory
        . $tail;

    if (file_put_contents($path, $patched) === false) {
        throw new RuntimeException('Unable to write patched EPUB ZIP local header');
    }
}

