    'records epub ocf mimetype diagnostics' => static function (TestRunner $t): void {
        $addMinimalPackage = static function (ZipArchive $zip): void {
            $zip->addFromString('META-INF/container.xml', '<?xml version="1.0"?><container xmlns="urn:oasis:names:tc:opendocument:xmlns:container"><rootfiles><rootfile full-path="EPUB/package.opf" media-type="application/oebps-package+xml"/></rootfiles></container>');
            $zip->addFromString('EPUB/package.opf', <<<'XML'
<?xml version="1.0" encoding="UTF-8"?>
<package xmlns="http://www.idpf.org/2007/opf"
         xmlns:dc="http://purl.org/dc/elements/1.1/"
         xmlns:dcterms="http://purl.org/dc/terms/"
         version="3.0"
         unique-identifier="book-id">
  <metadata>
    <dc:identifier id="book-id">urn:uuid:ocf-mimetype-diagnostics</dc:identifier>
    <dc:title>OCF Mimetype Diagnostics</dc:title>
    <dc:language>en</dc:language>
    <meta property="dcterms:modified">2026-06-22T00:00:00Z</meta>
  </metadata>
  <manifest>
    <item id="chapter" href="chapter.xhtml" media-type="application/xhtml+xml"/>
    <item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/>
  </manifest>
  <spine>
    <itemref idref="chapter"/>
  </spine>
</package>
XML);
            $zip->addFromString('EPUB/chapter.xhtml', '<html xmlns="http://www.w3.org/1999/xhtml"><body><h1>OCF Mimetype Diagnostics</h1><p>Readable mimetype diagnostic content.</p></body></html>');
            $zip->addFromString('EPUB/nav.xhtml', '<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops"><body><nav epub:type="toc"><ol><li><a href="chapter.xhtml">OCF Mimetype Diagnostics</a></li></ol></nav></body></html>');
        };

        $missingPath = tempnam(sys_get_temp_dir(), 'pandoc-epub-missing-mimetype-');
        $invalidPath = tempnam(sys_get_temp_dir(), 'pandoc-epub-invalid-mimetype-');
        $extraPath = tempnam(sys_get_temp_dir(), 'pandoc-epub-extra-mimetype-');
        if ($missingPath === false || $invalidPath === false || $extraPath === false) {
            throw new RuntimeException('Unable to create temporary EPUB path');
        }

        $missingZip = new ZipArchive();
        if ($missingZip->open($missingPath, ZipArchive::OVERWRITE) !== true) {
            throw new RuntimeException('Unable to create temporary EPUB package');
        }
        $addMinimalPackage($missingZip);
        $missingZip->close();

        $invalidZip = new ZipArchive();
        if ($invalidZip->open($invalidPath, ZipArchive::OVERWRITE) !== true) {
            throw new RuntimeException('Unable to create temporary EPUB package');
        }
        $addMinimalPackage($invalidZip);
        $invalidZip->addFromString('mimetype', "application/epub+zip\n");
        if (!$invalidZip->setCompressionName('mimetype', ZipArchive::CM_DEFLATE)) {
            throw new RuntimeException('Unable to deflate invalid EPUB mimetype fixture');
        }
        $invalidZip->close();

        $extraZip = pandoc_epub_test_zip($extraPath);
        $addMinimalPackage($extraZip);
        $extraZip->close();
        pandoc_epub_test_add_first_local_extra_field($extraPath, "\x55\x54\x00\x00");

        try {
            $missingMeta = (new EpubReader())->readEpubFile($missingPath)->attr('meta');
            $invalidMeta = (new EpubReader())->readEpubFile($invalidPath)->attr('meta');
            $extraMeta = (new EpubReader())->readEpubFile($extraPath)->attr('meta');
        } finally {
            @unlink($missingPath);
            @unlink($invalidPath);
            @unlink($extraPath);
        }

        $missingDiagnostics = $missingMeta['epubDiagnostics'] ?? [];
        $missingByCode = [];
        foreach ($missingDiagnostics as $diagnostic) {
            $code = (string) ($diagnostic['code'] ?? '');
            if ($code !== '') {
                $missingByCode[$code][] = $diagnostic;
            }
        }
        $t->same(count($missingDiagnostics), $missingMeta['epubDiagnosticCount']);
        $t->same(1, $missingMeta['epubDiagnosticErrorCount']);
        $t->same(0, $missingMeta['epubDiagnosticWarningCount']);
        $t->same('META-INF/container.xml', $missingByCode['missing-ocf-mimetype'][0]['firstEntry'] ?? null);
        $t->same(false, $missingMeta['epubOcfMimetype']['present'] ?? null);
        $t->same(false, $missingMeta['epubOcfMimetype']['first'] ?? null);

        $invalidDiagnostics = $invalidMeta['epubDiagnostics'] ?? [];
        $invalidByCode = [];
        foreach ($invalidDiagnostics as $diagnostic) {
            $code = (string) ($diagnostic['code'] ?? '');
            if ($code !== '') {
                $invalidByCode[$code][] = $diagnostic;
            }
        }
        $t->same(count($invalidDiagnostics), $invalidMeta['epubDiagnosticCount']);
        $t->same(3, $invalidMeta['epubDiagnosticErrorCount']);
        $t->same(0, $invalidMeta['epubDiagnosticWarningCount']);
        $t->same('META-INF/container.xml', $invalidByCode['ocf-mimetype-not-first'][0]['firstEntry'] ?? null);
        $t->same("application/epub+zip\n", $invalidByCode['invalid-ocf-mimetype-content'][0]['value'] ?? null);
        $t->same(21, $invalidByCode['invalid-ocf-mimetype-content'][0]['bytes'] ?? null);
        $t->same(ZipArchive::CM_DEFLATE, $invalidByCode['compressed-ocf-mimetype'][0]['compressionMethod'] ?? null);
        $t->same('application/epub+zip' . "\n", $invalidMeta['epubOcfMimetype']['mediaType'] ?? null);
        $t->same(ZipArchive::CM_DEFLATE, $invalidMeta['epubOcfMimetype']['compressionMethod'] ?? null);

        $extraDiagnostics = $extraMeta['epubDiagnostics'] ?? [];
        $extraByCode = [];
        foreach ($extraDiagnostics as $diagnostic) {
            $code = (string) ($diagnostic['code'] ?? '');
            if ($code !== '') {
                $extraByCode[$code][] = $diagnostic;
            }
        }
        $t->same(count($extraDiagnostics), $extraMeta['epubDiagnosticCount']);
        $t->same(1, $extraMeta['epubDiagnosticErrorCount']);
        $t->same(0, $extraMeta['epubDiagnosticWarningCount']);
        $t->same(4, $extraByCode['ocf-mimetype-extra-field'][0]['extraBytes'] ?? null);
        $t->same('mimetype', $extraByCode['ocf-mimetype-extra-field'][0]['localHeaderName'] ?? null);
        $t->same('mimetype', $extraMeta['epubOcfMimetype']['localHeaderName'] ?? null);
        $t->same(4, $extraMeta['epubOcfMimetype']['localHeaderExtraBytes'] ?? null);
    },
