        $semanticElements = is_array($meta['epubSpineItemRefs'][0]['semanticElements'] ?? null) ? $meta['epubSpineItemRefs'][0]['semanticElements'] : [];
        $semanticById = static function (string $id) use ($semanticElements): ?array {
