    'preserves epub3 details summary blocks through xhtml spine conversion' => static function (TestRunner $t): void {
        $path = tempnam(sys_get_temp_dir(), 'pandoc-epub-details-');
        if ($path === false) {
            throw new RuntimeException('Unable to create temporary EPUB path');
        }

        $zip = pandoc_epub_test_zip($path);
        $zip->addFromString('META-INF/container.xml', '<?xml version="1.0"?><container xmlns="urn:oasis:names:tc:opendocument:xmlns:container"><rootfiles><rootfile full-path="OPS/package.opf" media-type="application/oebps-package+xml"/></rootfiles></container>');
        $zip->addFromString('OPS/package.opf', <<<'XML'
<?xml version="1.0" encoding="UTF-8"?>
<package xmlns="http://www.idpf.org/2007/opf"
         xmlns:dc="http://purl.org/dc/elements/1.1/"
         version="3.0">
  <metadata>
    <dc:title>Details EPUB</dc:title>
  </metadata>
  <manifest>
    <item id="chapter" href="chapter.xhtml" media-type="application/xhtml+xml"/>
    <item id="source" href="media/source.xhtml" media-type="application/xhtml+xml"/>
    <item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/>
  </manifest>
  <spine>
    <itemref idref="chapter"/>
  </spine>
</package>
XML);
        $zip->addFromString('OPS/chapter.xhtml', <<<'HTML'
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
  <body>
    <h1>Details EPUB</h1>
    <details id="answer" class="reveal" open="open" epub:type="learning-resource" aria-label="Answer panel">
      <summary id="answer-summary">Answer key</summary>
      <p>Visible explanation with <a href="media/source.xhtml">source</a>.</p>
    </details>
  </body>
</html>
HTML);
        $zip->addFromString('OPS/media/source.xhtml', '<html xmlns="http://www.w3.org/1999/xhtml"><body><p>Source.</p></body></html>');
        $zip->addFromString('OPS/nav.xhtml', '<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops"><body><nav epub:type="toc"><ol><li><a href="chapter.xhtml">Details EPUB</a></li></ol></nav></body></html>');
        $zip->close();

        try {
            $document = (new EpubReader())->readEpubFile($path);
            $blocks = (new WordPressBlockWriter())->write($document);
        } finally {
            @unlink($path);
        }

        $details = array_values(array_filter($document->children, static fn ($node): bool => $node instanceof PortLibs\Pandoc\AstNode && $node->type === 'raw_html'));
        $detail = $details[0] ?? null;
        if (!$detail instanceof PortLibs\Pandoc\AstNode) {
            throw new RuntimeException('EPUB details test did not produce a raw HTML details block.');
        }

        $meta = $document->attr('meta');
        $semanticElements = is_array($meta['epubSpineItemRefs'][0]['semanticElements'] ?? null) ? $meta['epubSpineItemRefs'][0]['semanticElements'] : [];
        $detailsRecord = array_values(array_filter($semanticElements, static fn (array $entry): bool => ($entry['element'] ?? '') === 'details' && ($entry['id'] ?? '') === 'answer'))[0] ?? null;
        $summaryRecord = array_values(array_filter($semanticElements, static fn (array $entry): bool => ($entry['element'] ?? '') === 'summary' && ($entry['id'] ?? '') === 'answer-summary'))[0] ?? null;
        $expectedDetails = '<details id="answer" class="reveal" open="open" epub:type="learning-resource" aria-label="Answer panel"><summary id="answer-summary">Answer key</summary><p>Visible explanation with <a href="OPS/media/source.xhtml">source</a>.</p></details>';
        $actualDetails = preg_replace('/>\s+</u', '><', trim((string) $detail->attr('html')));
        $actualBlocks = preg_replace('/>\s+</u', '><', $blocks);
        $t->same($expectedDetails, $actualDetails);
        $t->same(1, substr_count($blocks, '<!-- wp:html -->'));
        $t->contains($expectedDetails, $actualBlocks);
        $t->true(in_array('OPS/media/source.xhtml', $meta['epubReferencedResources'], true), 'Details body links should still be tracked as referenced EPUB resources.');
        $t->true(!str_contains($blocks, 'Answer keyVisible explanation'), 'EPUB details should not flatten summary and body text into one paragraph.');
        $t->same('learning-resource', is_array($detailsRecord) ? ($detailsRecord['epubType'] ?? null) : null);
        $t->same(['reveal'], is_array($detailsRecord) ? ($detailsRecord['classes'] ?? null) : null);
        $t->same('Answer panel', is_array($detailsRecord) ? ($detailsRecord['ariaLabel'] ?? null) : null);
        $t->same(true, is_array($detailsRecord) ? ($detailsRecord['open'] ?? null) : null);
        $t->same('Answer key Visible explanation with source.', is_array($detailsRecord) ? ($detailsRecord['text'] ?? null) : null);
        $t->same('Answer key', is_array($summaryRecord) ? ($summaryRecord['text'] ?? null) : null);
    },
    'reads epub bytes through the converter input path' => static function (TestRunner $t): void {
        $path = tempnam(sys_get_temp_dir(), 'pandoc-epub-');
        if ($path === false) {
            throw new RuntimeException('Unable to create temporary EPUB path');
        }

        $zip = pandoc_epub_test_zip($path);
        $zip->addFromString('META-INF/container.xml', '<?xml version="1.0"?><container xmlns="urn:oasis:names:tc:opendocument:xmlns:container"><rootfiles><rootfile full-path="package.opf" media-type="application/oebps-package+xml"/></rootfiles></container>');
        $zip->addFromString('package.opf', '<?xml version="1.0"?><package xmlns="http://www.idpf.org/2007/opf" xmlns:dc="http://purl.org/dc/elements/1.1/"><metadata><dc:title>Byte EPUB</dc:title></metadata><manifest><item id="c1" href="chapter.xhtml" media-type="application/xhtml+xml"/></manifest><spine><itemref idref="c1"/></spine></package>');
        $zip->addFromString('chapter.xhtml', '<html xmlns="http://www.w3.org/1999/xhtml"><body><h1>Byte EPUB</h1><p>Body.</p></body></html>');
        $zip->close();

        try {
            $bytes = file_get_contents($path);
            if (!is_string($bytes)) {
                throw new RuntimeException('Unable to read temporary EPUB package');
            }
            $document = PandocConverter::read($bytes, 'epub');
        } finally {
            @unlink($path);
        }

        $t->same('Byte EPUB', $document->attr('meta')['title']);
        $t->same('heading', $document->children[0]->type);
        $t->same('Byte EPUB', $document->children[0]->attr('text'));
    },
