    <dc:creator id="creator-primary">Alice Example</dc:creator>
    <dc:language>en</dc:language>
    <meta property="dcterms:modified">2026-06-22T00:00:00Z</meta>
    <meta property="title-type" refines="#title-main">main</meta>
    <meta id="missing-meta-ref" property="display-seq" refines="#missing-creator">1</meta>
    <link id="missing-link-ref" href="metadata/onix.xml" rel="alternate" media-type="application/xml" refines="#missing-record"/>
    <meta id="chapter-resource-ref" property="source-of" refines="chapter.xhtml">pagination</meta>
    <meta id="package-path-ref" property="title-type" refines="package.opf#title-main">main</meta>
    <link id="metadata-resource-ref" href="metadata/onix.xml" rel="alternate" media-type="application/xml" refines="metadata/onix.xml#record"/>
    <meta id="missing-resource-ref" property="source-of" refines="missing.xhtml#missing">pagination</meta>
  </metadata>
  <manifest>
    <item id="chapter" href="chapter.xhtml" media-type="application/xhtml+xml"/>
    <item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/>
  </manifest>
  <spine>
    <itemref idref="chapter"/>
  </spine>
