XML);
        $zip->addFromString('OPS/chapter.xhtml', '<html xmlns="http://www.w3.org/1999/xhtml"><body><h1>Refines Diagnostics</h1><p>Readable chapter content.</p></body></html>');
        $zip->addFromString('OPS/nav.xhtml', '<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops"><body><nav epub:type="toc"><ol><li><a href="chapter.xhtml">Refines Diagnostics</a></li></ol></nav></body></html>');
        $zip->addFromString('OPS/metadata/onix.xml', '<onix><record id="record">metadata</record></onix>');
        $zip->close();

        try {
            $document = (new EpubReader())->readEpubFile($path);
            $meta = $document->attr('meta');
            $blocks = (new WordPressBlockWriter())->write($document);
        } finally {
            @unlink($path);
        }

        $diagnostics = $meta['epubDiagnostics'] ?? [];
        $byCode = [];
        foreach ($diagnostics as $diagnostic) {
            $code = (string) ($diagnostic['code'] ?? '');
            if ($code !== '') {
                $byCode[$code][] = $diagnostic;
            }
        }

        $t->same(count($diagnostics), $meta['epubDiagnosticCount']);
        $t->same(3, $meta['epubDiagnosticErrorCount']);
        $t->same(0, $meta['epubDiagnosticWarningCount']);
        $t->same(2, count($byCode['missing-metadata-refines-target'] ?? []));
        $t->same('missing-meta-ref', $byCode['missing-metadata-refines-target'][0]['id'] ?? null);
        $t->same('display-seq', $byCode['missing-metadata-refines-target'][0]['property'] ?? null);
        $t->same('#missing-creator', $byCode['missing-metadata-refines-target'][0]['refines'] ?? null);
        $t->same('missing-link-ref', $byCode['missing-metadata-refines-target'][1]['id'] ?? null);
        $t->same('link', $byCode['missing-metadata-refines-target'][1]['element'] ?? null);
        $t->same('#missing-record', $byCode['missing-metadata-refines-target'][1]['refines'] ?? null);
        $t->same(1, count($byCode['missing-metadata-refines-resource'] ?? []));
        $t->same('missing-resource-ref', $byCode['missing-metadata-refines-resource'][0]['id'] ?? null);
        $t->same('source-of', $byCode['missing-metadata-refines-resource'][0]['property'] ?? null);
        $t->same('missing.xhtml#missing', $byCode['missing-metadata-refines-resource'][0]['refines'] ?? null);
        $t->same('OPS/missing.xhtml', $byCode['missing-metadata-refines-resource'][0]['path'] ?? null);
        $t->same('missing', $byCode['missing-metadata-refines-resource'][0]['fragment'] ?? null);
        $t->true(!str_contains(json_encode($diagnostics), '#title-main'), 'Valid metadata refinement targets should not be reported.');
        $t->true(!str_contains(json_encode($diagnostics), 'chapter-resource-ref'), 'Existing resource refines targets should not be reported.');
        $t->true(!str_contains(json_encode($diagnostics), 'package-path-ref'), 'Package path plus fragment refines targets should resolve to package element ids.');
        $t->true(!str_contains(json_encode($diagnostics), 'metadata-resource-ref'), 'Existing linked metadata resource refines targets should not be reported.');
        $t->same('OPS/chapter.xhtml', $meta['epubSpineItemRefs'][0]['path'] ?? null);
        $t->contains('Readable chapter content.', $blocks);
    },
